/**
 * TASK: Complete the RgbColor record.
 *
 * Static factory:
 * - fromHex(text) accepts "#1E90FF" or "1e90ff" (the leading # is optional and
 *   the letters may be any case) and returns the matching RgbColor.
 *   Anything that is not exactly six hex digits (after an optional #), or a
 *   null, must throw new IllegalArgumentException("bad hex: " + text).
 *
 * Derived accessors -- these compute from the components, they store nothing:
 * - hex() gives the canonical text back: "#1E90FF" (always a #, upper case,
 *   two digits per channel, so black is "#000000").
 * - brightness() is the integer (red * 299 + green * 587 + blue * 114) / 1000
 *   using ordinary integer division.
 * - isDark() is true when brightness() is below 128.
 *
 * Example: RgbColor.fromHex("#1E90FF") -> RgbColor(30, 144, 255),
 * whose brightness() is 122 and whose isDark() is true.
 */
public record RgbColor(int red, int green, int blue) {

    public static RgbColor fromHex(String text) {
        if (text == null) {
            throw new IllegalArgumentException("bad hex: " + text);
        }
        String digits = text.startsWith("#") ? text.substring(1) : text;
        if (!digits.matches("[0-9a-fA-F]{6}")) {
            throw new IllegalArgumentException("bad hex: " + text);
        }
        int r = Integer.parseInt(digits.substring(0, 2), 16);
        int g = Integer.parseInt(digits.substring(2, 4), 16);
        int b = Integer.parseInt(digits.substring(4, 6), 16);
        return new RgbColor(r, g, b);
    }

    public String hex() {
        return String.format(java.util.Locale.US, "#%02X%02X%02X", red, green, blue);
    }

    public int brightness() {
        return (red * 299 + green * 587 + blue * 114) / 1000;
    }

    public boolean isDark() {
        return brightness() < 128;
    }
}
